101	 * Parses a raw string as a positive integer insight ID.
102	 *
103	 * Rejects:
104	 * - Non-numeric strings (NaN after Number())
105	 * - Floating-point strings (any string containing '.', e.g. "1.5", "2.0")
106	 * - Zero or negative integers
107	 *
108	 * The decimal-point check is performed on the raw string before numeric
109	 * coercion so that "2.0" (which coerces to an integer) is still rejected.
110	 *
111	 * @throws ApiError VALIDATION_ERROR for any rejected value.
112	 */
113	export function parseKnowledgeId(raw: string): number {
114	  // Reject strings containing a decimal point before numeric coercion —
115	  // this catches "1.5" and also "2.0", both of which the caller must treat
116	  // as non-integer IDs even though Number("2.0") === 2.
117	  if (raw.includes('.')) {
118	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
119	  }
120	  const n = Number(raw);
121	  if (!Number.isInteger(n) || n <= 0) {
122	    throw new ApiError('VALIDATION_ERROR', 'Invalid insight id.');
123	  }
124	  return n;
125	}
