201	/**
202	 * Updates an existing knowledge insight identified by its numeric ID.
203	 *
204	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
205	 * for non-integer, zero, or floating-point strings). Validates the request body
206	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
207	 * type mismatches). Extracts `scope` and `repository_name` discriminator fields to
208	 * scope the update to the correct store.
209	 *
210	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
211	 * cleared (removed) on the stored insight.
212	 *
213	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
214	 *
215	 * @param ledgerRoot  Absolute path to the central ledger root.
216	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
217	 * @param body        Parsed request body (any shape — validated here).
218	 * @returns The updated Insight.
219	 */
220	export async function handleUpdateKnowledge(
221	  ledgerRoot: string,
222	  rawId: string,
223	  body: unknown
224	): Promise<Insight> {
225	  const id = parseKnowledgeId(rawId);
226	
227	  const parseResult = KnowledgeUpdateBodySchema.safeParse(body);
228	  if (!parseResult.success) {
229	    validationError('Invalid knowledge update body.', parseResult.error.issues);
230	  }
231	
232	  const { scope, repository_name, superseded_by, ...rest } = parseResult.data;
233	
234	  // Map superseded_by: null → undefined so the field is cleared on the stored insight.
235	  const updates: Parameters<KnowledgeStoreManager['updateInsight']>[1] = {
236	    ...rest,
237	    ...(superseded_by === null ? { superseded_by: undefined } : superseded_by !== undefined ? { superseded_by } : {}),
238	  };
239	
240	  const manager = new KnowledgeStoreManager(ledgerRoot);
241	
242	  try {
243	    return await manager.updateInsight(id, updates, { scope, repository_name });
244	  } catch (err) {
245	    const msg = err instanceof Error ? err.message : String(err);
246	    if (msg.includes('not found')) {
247	      throw new ApiError('NOT_FOUND', 'Insight not found.');
248	    }
249	    throw err;
250	  }
251	}
